INSERT INTO `about_page_content` (`id`, `breadcrumb_image_path`, `breadcrumb_image_alt`, `breadcrumb_heading_type`, `breadcrumb_heading_text`, `breadcrumb_description`, `about_featured_image_path`, `about_featured_image_alt`, `about_heading_type`, `about_heading_text`, `about_description`, `about_processed_description`, `owner_image_1_path`, `owner_image_1_alt`, `owner_image_2_path`, `owner_image_2_alt`, `owner_heading_1_type`, `owner_heading_1_text`, `owner_heading_2_type`, `owner_heading_2_text`, `owner_description`, `owner_processed_description`, `meta_data`, `created_at`, `updated_at`) VALUES
(1, 'pages/about//gU0jQ08ZjCl3VKs6qXu69KSS0vua9WibfcKiFrwv.jpg', 'Welcome to Dolphin Events in UK', 'h1', 'Who we are? Welcome to Dolphin Events in UK', 'At Dolphin Events, we are passionate about bringing people together through the magic of live events. Founded by the creative minds behind Dolphin Studios, we originally launched this platform to streamline ticket sales for our own exciting events. Today, we are proud to open our doors to everyone, offering a seamless ticketing solution for event organisers and attendees across the UK.\r\n\r\nWhether you’re looking to attend a concert, theatre show, festival, or any live gathering, Dolphin Events makes ticket purchasing easy, secure, and enjoyable. Our user-friendly interface, robust payment systems, and responsive customer support ensure a smooth experience from start to finish.\r\n\r\nWe are also the proud owners of Radio Lemon Live UK, further extending our reach within the entertainment industry and providing additional promotional opportunities for events featured on our platform. Whether you’re here to book your next adventure or to showcase your own event, Dolphin Events is your trusted partner in creating and enjoying memorable experiences. Let’s make every event extraordinary—together!', 'pages/about//swaffVpNrgFDzZONVq7yzEtaYsm4ZYgIjXkvxjlv.jpg', 'Welcome to Dolphin Events in UK', 'h2', 'Some thing about Our Company', 'At Dolphin Events, we are passionate about bringing people together through the magic of live events. Founded by the creative minds behind Dolphin Studios, we originally launched this platform to streamline ticket sales for our own exciting events. Today, we are proud to open our doors to everyone, offering a seamless ticketing solution for event organisers and attendees across the UK.\r\n\r\nWhether you’re looking to attend a concert, theatre show, festival, or any live gathering, Dolphin Events makes ticket purchasing easy, secure, and enjoyable. Our user-friendly interface, robust payment systems, and responsive customer support ensure a smooth experience from start to finish.\r\n\r\nWe are also the proud owners of Radio Lemon Live UK, further extending our reach within the entertainment industry and providing additional promotional opportunities for events featured on our platform. Whether you’re here to book your next adventure or to showcase your own event, Dolphin Events is your trusted partner in creating and enjoying memorable experiences. Let’s make every event extraordinary—together!', '<p>At Dolphin Events, we are passionate about bringing people together through the magic of live events. Founded by the creative minds behind Dolphin Studios, we originally launched this platform to streamline ticket sales for our own exciting events. Today, we are proud to open our doors to everyone, offering a seamless ticketing solution for event organisers and attendees across the UK.</p><p>Whether you’re looking to attend a concert, theatre show, festival, or any live gathering, Dolphin Events makes ticket purchasing easy, secure, and enjoyable. Our user-friendly interface, robust payment systems, and responsive customer support ensure a smooth experience from start to finish.</p><p>We are also the proud owners of Radio Lemon Live UK, further extending our reach within the entertainment industry and providing additional promotional opportunities for events featured on our platform. Whether you’re here to book your next adventure or to showcase your own event, Dolphin Events is your trusted partner in creating and enjoying memorable experiences. Let’s make every event extraordinary—together!</p>', 'pages/about/owner/vBXioyKp8tsAUltbfo4xduMOvbTbmgkhqiEzEzcS.jpg', 'about-owner-image', 'pages/about/owner/OYWeIWestZwsIgh0QccjcRHvMqg4whI5HRbfhFqq.jpg', 'about-owner-image', 'h3', 'Meet the owner', 'h3', 'Bibin Antony Mani', 'Bibin Antony Mani is the visionary entrepreneur behind Nammude Ireland Events and BookMySeats.ie — a passionate community builder, event organizer, and the driving force connecting Malayalis across Ireland.\r\n\r\nOriginally from Kerala, India, and a mechanical engineer by profession, Bibin made Ireland his home in July 2021. With a deep love for his roots and a strong desire to bring people together, he quickly recognized the need for a dedicated platform for the growing Malayali community in Ireland.\r\n\r\nIn 2023, he founded Nammude Ireland — an Instagram-based community that rapidly grew into one of the most vibrant online spaces for Malayalis across the country. Building on that momentum, he launched Nammude Ireland FM, a dedicated radio station crafted to keep the Malayali spirit alive, delivering local updates, cultural content, and a true sense of home — no matter where you are.\r\n\r\nWith over 25,000 Malayalis now calling Ireland home, Bibin saw the next natural step: bringing the community together beyond the screen. This inspired the creation of Nammude Ireland Events, a platform dedicated to organizing memorable cultural events, celebrations, and community gatherings across Ireland.\r\n\r\nTo make event access seamless and convenient for everyone, he launched BookMySeats.ie — a dedicated ticketing platform where the Irish Malayali community can effortlessly discover, book, and enjoy events that celebrate their culture and heritage.\r\n\r\nBibin\'s journey is a testament to the power of community, passion, and purpose — turning a simple idea into a thriving ecosystem that thousands of Malayalis across Ireland now call their own.', '<p>Bibin Antony Mani is the visionary entrepreneur behind Nammude Ireland Events and BookMySeats.ie — a passionate community builder, event organizer, and the driving force connecting Malayalis across Ireland.</p><p>Originally from Kerala, India, and a mechanical engineer by profession, Bibin made Ireland his home in July 2021. With a deep love for his roots and a strong desire to bring people together, he quickly recognized the need for a dedicated platform for the growing Malayali community in Ireland.</p><p>In 2023, he founded Nammude Ireland — an Instagram-based community that rapidly grew into one of the most vibrant online spaces for Malayalis across the country. Building on that momentum, he launched Nammude Ireland FM, a dedicated radio station crafted to keep the Malayali spirit alive, delivering local updates, cultural content, and a true sense of home — no matter where you are.</p><p>With over 25,000 Malayalis now calling Ireland home, Bibin saw the next natural step: bringing the community together beyond the screen. This inspired the creation of Nammude Ireland Events, a platform dedicated to organizing memorable cultural events, celebrations, and community gatherings across Ireland.</p><p>To make event access seamless and convenient for everyone, he launched BookMySeats.ie — a dedicated ticketing platform where the Irish Malayali community can effortlessly discover, book, and enjoy events that celebrate their culture and heritage.</p><p>Bibin\'s journey is a testament to the power of community, passion, and purpose — turning a simple idea into a thriving ecosystem that thousands of Malayalis across Ireland now call their own.</p>', '\"<title>About Us | BookMySeats.ie \\u2013 Ireland\'s Malayali Event Ticketing Platform<\\/title>\\r\\n<meta name=\\\"description\\\"\\r\\n    content=\\\"Learn about BookMySeats.ie \\u2013 founded by Bibin Antony Mani, the platform connecting over 25,000 Malayalis across Ireland through cultural events, celebrations, and community gatherings.\\\" \\/>\\r\\n<meta name=\\\"keywords\\\" content=\\\"BookMySeats about us, Bibin Antony Mani, Nammude Ireland Events, Malayali events Ireland, Kerala community Ireland, Irish Malayali platform, event tickets Ireland, Nammude Ireland FM\\\" \\/>\\r\\n<meta name=\\\"author\\\" content=\\\"Bibin Antony Mani \\u2013 Nammude Ireland Events\\\" \\/>\\r\\n\\r\\n<!-- Canonical URL -->\\r\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/bookmyseats.ie\\/about\\\" \\/>\\r\\n\\r\\n<!-- Open Graph Meta Tags -->\\r\\n<meta property=\\\"og:title\\\" content=\\\"About Us | BookMySeats.ie \\u2013 Ireland\'s Malayali Event Ticketing Platform\\\" \\/>\\r\\n<meta property=\\\"og:description\\\"\\r\\n    content=\\\"BookMySeats.ie is Ireland\'s dedicated Malayali event ticketing platform, founded by Bibin Antony Mani. Discover our story and mission to keep the Malayali spirit alive in Ireland.\\\" \\/>\\r\\n<meta property=\\\"og:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/about\\\" \\/>\\r\\n<meta property=\\\"og:type\\\" content=\\\"website\\\" \\/>\\r\\n\\r\\n<!-- Twitter Card Meta Tags -->\\r\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\r\\n<meta name=\\\"twitter:title\\\" content=\\\"About Us | BookMySeats.ie \\u2013 Ireland\'s Malayali Event Ticketing Platform\\\" \\/>\\r\\n<meta name=\\\"twitter:description\\\"\\r\\n    content=\\\"BookMySeats.ie is Ireland\'s dedicated Malayali event ticketing platform, founded by Bibin Antony Mani. Discover our story and mission to keep the Malayali spirit alive in Ireland.\\\" \\/>\\r\\n<meta name=\\\"twitter:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n\\r\\n<!-- Structured Data (JSON-LD Schema) -->\\r\\n<script type=\\\"application\\/ld+json\\\">\\r\\n{\\r\\n    \\\"@context\\\": \\\"https:\\/\\/schema.org\\/\\\",\\r\\n    \\\"@type\\\": \\\"AboutPage\\\",\\r\\n    \\\"name\\\": \\\"About Us \\u2013 BookMySeats.ie\\\",\\r\\n    \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\/about\\\",\\r\\n    \\\"description\\\": \\\"BookMySeats.ie is Ireland\'s dedicated event ticketing platform for the Malayali community, founded by Bibin Antony Mani. From cultural festivals to community gatherings, we bring Malayalis together across Ireland.\\\",\\r\\n    \\\"image\\\": \\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\",\\r\\n    \\\"publisher\\\": {\\r\\n        \\\"@type\\\": \\\"Organization\\\",\\r\\n        \\\"name\\\": \\\"BookMySeats.ie\\\",\\r\\n        \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\\",\\r\\n        \\\"logo\\\": \\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\",\\r\\n        \\\"foundingDate\\\": \\\"2023\\\",\\r\\n        \\\"founder\\\": {\\r\\n            \\\"@type\\\": \\\"Person\\\",\\r\\n            \\\"name\\\": \\\"Bibin Antony Mani\\\",\\r\\n            \\\"jobTitle\\\": \\\"Founder & CEO\\\",\\r\\n            \\\"nationality\\\": \\\"Indian\\\",\\r\\n            \\\"description\\\": \\\"Bibin Antony Mani is a mechanical engineer from Kerala, India, who moved to Ireland in 2021. He is the founder of Nammude Ireland, Nammude Ireland FM, Nammude Ireland Events, and BookMySeats.ie.\\\"\\r\\n        },\\r\\n        \\\"address\\\": {\\r\\n            \\\"@type\\\": \\\"PostalAddress\\\",\\r\\n            \\\"addressCountry\\\": \\\"IE\\\"\\r\\n        },\\r\\n        \\\"sameAs\\\": [\\r\\n            \\\"https:\\/\\/www.instagram.com\\/nammudeireland\\\",\\r\\n            \\\"https:\\/\\/www.facebook.com\\/nammudeireland\\\"\\r\\n        ]\\r\\n    }\\r\\n}\\r\\n<\\/script>\"', '2025-10-18 03:12:21', '2026-08-20 12:31:10');
