(1, 'pages/contact//Aq4VL6DF2Q6SmsCxMYHjVmR4Rk6Vxm4ofqwyZXji.jpg', 'breadcrumb-image', 'h1', 'Contact Us', 'Whether you\'re looking for support with your tickets, want to partner with us for an upcoming event, or simply want to get in touch — our team is always here to help.', '+353', '892292277', '+353', '892292277', 'support@bookmyseats.ie', '9th Station ManorTullow, Co. CarlowIreland - R93CA25', 'https://maps.app.goo.gl/Y1acFg7Yi1eW7FJv5', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3451.2880717917096!2d72.860237074721!3d19.09022275152681!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3be7c85099bd2947%3A0x1ecc1a60c474a8ae!2sChhatrapati%20Shivaji%20Maharaj%20International%20Airport!5e1!3m2!1sen!2sin!4v1727170488085!5m2https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d16356.919190862463!2d-6.775432800252814!3d52.80289132818182!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x485d5f0d616e7211%3A0xa00c7a997318c90!2sTullowphelim%2C%20Tullow%2C%20Co.%20Carlow%2C%20Ireland!5e1!3m2!1sen!2sin!4v1780073890646!5m2!1sen!2sin', '\"<title>Contact Us | BookMySeats.ie \\u2013 Book Malayali Events in Ireland<\\/title>\\r\\n<meta name=\\\"description\\\"\\r\\n    content=\\\"Get in touch with BookMySeats.ie \\u2013 Ireland\'s dedicated Malayali event ticketing platform. We\'re here to help with bookings, event listings, and partnerships.\\\" \\/>\\r\\n<meta name=\\\"keywords\\\" content=\\\"BookMySeats, contact BookMySeats, Malayali events Ireland, Irish Malayali community, Nammude Ireland Events, event tickets Ireland, Kerala events Ireland\\\" \\/>\\r\\n<meta name=\\\"author\\\" content=\\\"Bibin Antony Mani \\u2013 Nammude Ireland Events\\\" \\/>\\r\\n\\r\\n<!-- Canonical URL -->\\r\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/bookmyseats.ie\\/contact\\\" \\/>\\r\\n\\r\\n<!-- Open Graph Meta Tags -->\\r\\n<meta property=\\\"og:title\\\" content=\\\"Contact Us | BookMySeats.ie\\\" \\/>\\r\\n<meta property=\\\"og:description\\\"\\r\\n    content=\\\"Have a question or want to list your event? Reach out to BookMySeats.ie \\u2013 the trusted event ticketing platform for the Malayali community in Ireland.\\\" \\/>\\r\\n<meta property=\\\"og:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/contact\\\" \\/>\\r\\n<meta property=\\\"og:type\\\" content=\\\"website\\\" \\/>\\r\\n\\r\\n<!-- Twitter Card Meta Tags -->\\r\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\r\\n<meta name=\\\"twitter:title\\\" content=\\\"Contact Us | BookMySeats.ie\\\" \\/>\\r\\n<meta name=\\\"twitter:description\\\"\\r\\n    content=\\\"Have a question or want to list your event? Reach out to BookMySeats.ie \\u2013 the trusted event ticketing platform for the Malayali community in Ireland.\\\" \\/>\\r\\n<meta name=\\\"twitter:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n\\r\\n<!-- Structured Data (JSON-LD Schema) -->\\r\\n<script type=\\\"application\\/ld+json\\\">\\r\\n{\\r\\n    \\\"@context\\\": \\\"https:\\/\\/schema.org\\/\\\",\\r\\n    \\\"@type\\\": \\\"ContactPage\\\",\\r\\n    \\\"name\\\": \\\"Contact Us \\u2013 BookMySeats.ie\\\",\\r\\n    \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\/contact\\\",\\r\\n    \\\"description\\\": \\\"Get in touch with BookMySeats.ie for event bookings, ticket support, event listings, and partnerships. Ireland\'s dedicated Malayali event ticketing platform.\\\",\\r\\n    \\\"image\\\": \\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\",\\r\\n    \\\"publisher\\\": {\\r\\n        \\\"@type\\\": \\\"Organization\\\",\\r\\n        \\\"name\\\": \\\"BookMySeats.ie\\\",\\r\\n        \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\\",\\r\\n        \\\"logo\\\": \\\"https:\\/\\/