INSERT INTO `home_page_content` (`id`, `show_what`, `hero_video_path`, `hero_video_poster`, `about_image_path`, `about_image_alt`, `about_heading_type_1`, `about_heading_text_1`, `about_heading_type_2`, `about_heading_text_2`, `about_description`, `about_processed_description`, `meta_data`, `created_at`, `updated_at`) VALUES
(1, 'slider', NULL, NULL, 'pages/home//VApmLT3qo44mIhk5ewNmbCmd1XLRKfgy3rrJJ19S.jpg', 'home-page-about-image', 'h3', 'Who we are?', 'h1', 'Welcome to Dolphin Events in UK', 'At Dolphin Events, we are passionate about bringing people together through the magic of live events. Founded by the creative minds behind Dolphin Studios, we originally launched this platform to streamline ticket sales for our own exciting events. Today, we are proud to open our doors to everyone, offering a seamless ticketing solution for event organisers and attendees across the UK.\r\n\r\nWhether you’re looking to attend a concert, theatre show, festival, or any live gathering, Dolphin Events makes ticket purchasing easy, secure, and enjoyable. Our user-friendly interface, robust payment systems, and responsive customer support ensure a smooth experience from start to finish.\r\n\r\nWe are also the proud owners of Radio Lemon Live UK, further extending our reach within the entertainment industry and providing additional promotional opportunities for events featured on our platform. Whether you’re here to book your next adventure or to showcase your own event, Dolphin Events is your trusted partner in creating and enjoying memorable experiences. Let’s make every event extraordinary—together!', '<p>At Dolphin Events, we are passionate about bringing people together through the magic of live events. Founded by the creative minds behind Dolphin Studios, we originally launched this platform to streamline ticket sales for our own exciting events. Today, we are proud to open our doors to everyone, offering a seamless ticketing solution for event organisers and attendees across the UK.</p><p>Whether you’re looking to attend a concert, theatre show, festival, or any live gathering, Dolphin Events makes ticket purchasing easy, secure, and enjoyable. Our user-friendly interface, robust payment systems, and responsive customer support ensure a smooth experience from start to finish.</p><p>We are also the proud owners of Radio Lemon Live UK, further extending our reach within the entertainment industry and providing additional promotional opportunities for events featured on our platform. Whether you’re here to book your next adventure or to showcase your own event, Dolphin Events is your trusted partner in creating and enjoying memorable experiences. Let’s make every event extraordinary—together!</p>', '\"<title>BookMySeats.ie \\u2013 Book Malayali Events in Ireland | Nammude Ireland Events<\\/title>\\r\\n<meta name=\\\"description\\\"\\r\\n    content=\\\"BookMySeats.ie is Ireland\'s #1 event ticketing platform for the Malayali community. Discover, book, and enjoy the best Kerala cultural events, festivals, and community gatherings across Ireland.\\\" \\/>\\r\\n<meta name=\\\"keywords\\\" content=\\\"BookMySeats, book event tickets Ireland, Malayali events Ireland, Kerala events Ireland, Irish Malayali community, Nammude Ireland Events, cultural events Ireland, Malayalam events Ireland, Kerala festival Ireland, event booking Ireland\\\" \\/>\\r\\n<meta name=\\\"author\\\" content=\\\"Bibin Antony Mani \\u2013 Nammude Ireland Events\\\" \\/>\\r\\n\\r\\n<!-- Canonical URL -->\\r\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/bookmyseats.ie\\/\\\" \\/>\\r\\n\\r\\n<!-- Open Graph Meta Tags -->\\r\\n<meta property=\\\"og:title\\\" content=\\\"BookMySeats.ie \\u2013 Book Malayali Events in Ireland\\\" \\/>\\r\\n<meta property=\\\"og:description\\\"\\r\\n    content=\\\"Ireland\'s dedicated Malayali event ticketing platform. Discover and book tickets for the best Kerala cultural events, festivals, and community gatherings across Ireland. Brought to you by Nammude Ireland Events.\\\" \\/>\\r\\n<meta property=\\\"og:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/\\\" \\/>\\r\\n<meta property=\\\"og:type\\\" content=\\\"website\\\" \\/>\\r\\n<meta property=\\\"og:site_name\\\" content=\\\"BookMySeats.ie\\\" \\/>\\r\\n<meta property=\\\"og:locale\\\" content=\\\"en_IE\\\" \\/>\\r\\n\\r\\n<!-- Twitter Card Meta Tags -->\\r\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\r\\n<meta name=\\\"twitter:title\\\" content=\\\"BookMySeats.ie \\u2013 Book Malayali Events in Ireland\\\" \\/>\\r\\n<meta name=\\\"twitter:description\\\"\\r\\n    content=\\\"Ireland\'s dedicated Malayali event ticketing platform. Discover and book tickets for the best Kerala cultural events, festivals, and community gatherings across Ireland.\\\" \\/>\\r\\n<meta name=\\\"twitter:image\\\" content=\\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\" \\/>\\r\\n<meta name=\\\"twitter:site\\\" content=\\\"@nammudeireland\\\" \\/>\\r\\n\\r\\n<!-- Structured Data (JSON-LD Schema) -->\\r\\n<script type=\\\"application\\/ld+json\\\">\\r\\n{\\r\\n    \\\"@context\\\": \\\"https:\\/\\/schema.org\\/\\\",\\r\\n    \\\"@type\\\": \\\"WebSite\\\",\\r\\n    \\\"name\\\": \\\"BookMySeats.ie\\\",\\r\\n    \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\/\\\",\\r\\n    \\\"description\\\": \\\"Ireland\'s dedicated Malayali event ticketing platform for discovering and booking Kerala cultural events, festivals, and community gatherings across Ireland.\\\",\\r\\n    \\\"image\\\": \\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\",\\r\\n    \\\"inLanguage\\\": \\\"en-IE\\\",\\r\\n    \\\"potentialAction\\\": {\\r\\n        \\\"@type\\\": \\\"SearchAction\\\",\\r\\n        \\\"target\\\": \\\"https:\\/\\/bookmyseats.ie\\/events?search={search_term_string}\\\",\\r\\n        \\\"query-input\\\": \\\"required name=search_term_string\\\"\\r\\n    },\\r\\n    \\\"publisher\\\": {\\r\\n        \\\"@type\\\": \\\"Organization\\\",\\r\\n        \\\"name\\\": \\\"BookMySeats.ie\\\",\\r\\n        \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\\",\\r\\n        \\\"logo\\\": {\\r\\n            \\\"@type\\\": \\\"ImageObject\\\",\\r\\n            \\\"url\\\": \\\"https:\\/\\/bookmyseats.ie\\/storage\\/pages\\/home\\/\\/cENyrT87wVgGNQ7yrPod8aH5EAQqznfEcKSnWQpV.jpg\\\"\\r\\n        },\\r\\n        \\\"foundingDate\\\": \\\"2023\\\",\\r\\n        \\\"founder\\\": {\\r\\n            \\\"@type\\\": \\\"Person\\\",\\r\\n            \\\"name\\\": \\\"Bibin Antony Mani\\\",\\r\\n            \\\"jobTitle\\\": \\\"Founder & CEO\\\"\\r\\n        },\\r\\n        \\\"address\\\": {\\r\\n            \\\"@type\\\": \\\"PostalAddress\\\",\\r\\n            \\\"addressCountry\\\": \\\"IE\\\"\\r\\n        },\\r\\n        \\\"sameAs\\\": [\\r\\n            \\\"https:\\/\\/www.instagram.com\\/nammudeireland\\\",\\r\\n            \\\"https:\\/\\/www.facebook.com\\/nammudeireland\\\"\\r\\n        ]\\r\\n    }\\r\\n}\\r\\n<\\/script>\"', '2025-10-18 02:42:56', '2026-08-20 12:35:56');
