INSERT INTO `policy_page_content` (`id`, `breadcrumb_image_path`, `breadcrumb_image_alt`, `breadcrumb_heading_type`, `breadcrumb_heading_text`, `breadcrumb_description`, `main_content`, `processed_main_content`, `meta_data`, `created_at`, `updated_at`) VALUES
(1, 'pages/policy//LNrxbtibzD3dLS8F3XAKWQMJ8YL9PYvVu1RWsXwC.jpg', 'breadcrumb-image', 'h4', 'Policy', 'Lorem ipsum dolor sit amet consectetur adipisicing elit. Iure aut, provident distinctio nobis nesciunt enim. Atque qui quasi itaque voluptatum dignissimos corrupti perspiciatis, beatae dolor vel?', 'This Privacy Policy outlines how BookMySeats.ie, owned by Nammude Ireland Entertainments, collects, uses, and protects your personal information when you use our website and services.\r\n\r\n**1. Information We Collect**\r\nWe may collect the following types of information:\r\n\r\n- Personal identification information (name, email address, phone number, etc.)\r\n- Payment information (credit card details, billing address, etc.)\r\n- Event-related information (event preferences, attendance history, etc.)\r\n\r\n**2. How We Use Your Information**\r\nYour information may be used in the following ways:\r\n\r\n- To process transactions and manage your bookings.\r\n- To improve customer service and respond to your inquiries.\r\n- To send periodic emails regarding your order or other products and services.\r\n- To personalize your experience on our website.\r\n\r\n**3. Data Protection**\r\nWe are committed to ensuring that your information is secure. We implement a variety of security measures to maintain the safety of your personal information when you place an order or enter, submit, or access your personal information.', '<p>This Privacy Policy outlines how BookMySeats.ie, owned by Nammude Ireland Entertainments, collects, uses, and protects your personal information when you use our website and services.</p><p><strong>1. Information We Collect</strong></p><p>We may collect the following types of information:</p><p>- Personal identification information (name, email address, phone number, etc.)</p><p>- Payment information (credit card details, billing address, etc.)</p><p>- Event-related information (event preferences, attendance history, etc.)</p><p><strong>2. How We Use Your Information</strong></p><p>Your information may be used in the following ways:</p><p>- To process transactions and manage your bookings.</p><p>- To improve customer service and respond to your inquiries.</p><p>- To send periodic emails regarding your order or other products and services.</p><p>- To personalize your experience on our website.</p><p><strong>3. Data Protection</strong></p><p>We are committed to ensuring that your information is secure. We implement a variety of security measures to maintain the safety of your personal information when you place an order or enter, submit, or access your personal information.</p>', 'null', '2025-10-18 04:19:39', '2026-02-16 04:50:57');
